// 扩展编辑AI (ExtEditAI) — 入口（自包含：UI 运行时已内联为 base64）
// 适配 ExtensionBuilder 插件宿主（ext-addons.js 的 evalAddonText）：
//   index.js 经 new Function('module','exports','Blockly','ctx','window', code) 求值，
//   宿主会把本文件的默认导出自动转换为 module.exports。
//   setup(ctx) 中的 ctx 由宿主在 applyExtAddons 时注入。
//
// 本文件把 lib/ai-assistant.umd.js（由 build-umd.cjs 生成，暴露 window.ExtEditAI_AIAssistant）
// 以 base64 内联，避免对同级 lib 资源文件的依赖；importAddonFromGithubDir 只会下载 index.js，
// 因此必须把 UI 运行时打包进 index.js 才能保证「一键安装」可用。

export default {
  id: 'extedit-ai',
  name: '扩展编辑AI',
  description: 'AI 助手，帮你编写/修改 Scratch / TurboWarp 扩展积木与代码。支持 OpenAI / 智谱 / DeepSeek / Anthropic 等多种模型，内置工作区读取、积木搜索、代码导出等工具调用。派生自 Gandi 插件 ai-assistant（Bilup Nova）。',
  category: '编辑器',
  recommended: true,
  credits: [
    { name: '白猫@CCW', link: 'https://www.ccw.site/student/6173f57f48cf8f4796fc860e' },
    { name: '酷可@CCW', link: 'https://www.ccw.site/student/610b508176415b2f27e0f851' },
    { name: 'PPN-design', link: '' },
    { name: 'RyaninCn11', link: '' },
  ],
  license: 'AGPL-3.0-or-later',
  repository: 'https://github.com/dhdbvcg/scratch-ext-addon/tree/main/extedit-ai',

  setup: async (ctx) => {
    const B = ctx.Blockly;
    const getWorkspace = ctx.getWorkspace;
    if (!B) {
      console.warn('[扩展编辑AI] 未找到 Blockly，无法激活');
      return () => {};
    }

    const React = (typeof window !== 'undefined' && window.React) || (typeof globalThis !== 'undefined' && globalThis.React);
    const ReactDOM = (typeof window !== 'undefined' && window.ReactDOM) || (typeof globalThis !== 'undefined' && globalThis.ReactDOM);
    if (!React || !ReactDOM) {
      console.warn('[扩展编辑AI] 未找到 React / ReactDOM 运行时，无法挂载 UI');
      return () => {};
    }

    // 注入面板所需 CSS（运行时 raw 注入）
    const css = [
      '.ext-ai-panel{position:absolute;top:0;left:0;right:0;bottom:0;background:#f0f2f5;display:flex;z-index:2000;font-family:-apple-system,"PingFang SC","Microsoft YaHei",system-ui,sans-serif;}',
      '.ext-ai-msg-bubble{padding:10px 14px;border-radius:12px;font-size:13px;line-height:1.55;white-space:pre-wrap;word-break:break-word;max-width:80%;}',
      '.ext-ai-msg-bubble pre{background:#1e1e1e;color:#d4d4d4;padding:10px 12px;border-radius:8px;overflow:auto;font-size:12px;margin:6px 0;}',
      '.ext-ai-msg-bubble code{font-family:Consolas,"Courier New",monospace;}',
      '.ext-ai-msg-bubble :not(pre)>code{background:#eceff1;padding:1px 5px;border-radius:4px;color:#c0341d;}',
      '.ext-ai-tool-call{background:#fff;border:1px solid #e8eaed;border-radius:8px;padding:8px 10px;margin:4px 0;font-size:12px;}',
      '.ext-ai-tool-call .name{font-weight:600;color:#1a73e8;}',
      '.ext-ai-tool-call .status-running{color:#f29900;}',
      '.ext-ai-tool-call .status-completed{color:#10b981;}',
      '.ext-ai-tool-call .status-error{color:#d93025;}',
      '.ext-ai-send-btn{background:#1a73e8;color:#fff;border:none;border-radius:8px;padding:10px 18px;cursor:pointer;font-size:14px;}',
      '.ext-ai-send-btn:disabled{opacity:.55;cursor:default;}',
      '.ext-ai-input{flex:1;border:1px solid #dadce0;border-radius:8px;padding:10px 12px;font-size:13px;resize:none;font-family:inherit;box-sizing:border-box;}',
      '.ext-ai-plugin-btn{background:#fff;border:1px solid #dadce0;border-radius:6px;padding:6px 12px;cursor:pointer;font-size:13px;color:#1a73e8;font-weight:500;}',
      '.ext-ai-plugin-btn:hover{background:#e8f0fe;}',
    ].join(String.fromCharCode(10));
    const styleEl = ctx.injectCSS ? ctx.injectCSS(css) : null;

    // 内联的 UI 运行时（base64 of lib/ai-assistant.umd.js）
    const UMD_B64 = '';

    let AIAssistant = null;
    try {
      const bin = atob(UMD_B64);
      const jsText = decodeURIComponent(escape(bin));
      const s = document.createElement('script');
      s.textContent = jsText;
      document.head.appendChild(s);
      AIAssistant = window.ExtEditAI_AIAssistant;
    } catch (e) {
      console.warn('[扩展编辑AI] 加载 UI 模块失败', e);
    }

    if (!AIAssistant) {
      console.warn('[扩展编辑AI] 未找到 UI 模块');
      return () => { if (styleEl && styleEl.remove) styleEl.remove(); };
    }

    // 挂载点
    const mountHost = document.createElement('div');
    mountHost.id = 'ext-ai-root';
    mountHost.style.display = 'none';
    const container = document.querySelector('.ext-builder-main') || document.body;
    container.appendChild(mountHost);

    let root = null;
    const openPanel = () => {
      mountHost.style.display = 'block';
      if (!root) root = ReactDOM.createRoot(mountHost);
      const ws = getWorkspace ? getWorkspace() : null;
      root.render(
        React.createElement(AIAssistant, {
          workspaceRef: { current: ws },
          javascriptGenerator: (typeof window !== 'undefined' && window._extBuilderGenerator) || null,
          customBlocksRef: { current: (typeof window !== 'undefined' && window._extBuilderCustomBlocks) || [] },
          onClose: () => { mountHost.style.display = 'none'; },
        })
      );
    };

    // 工具栏按钮
    const btn = ctx.addToolbarButton
      ? ctx.addToolbarButton('扩展编辑AI', openPanel, { title: '打开 AI 助手面板' })
      : (() => {
          const b = ctx.createElement('button', { className: 'ext-ai-plugin-btn', title: '打开 AI 助手面板' }, ['扩展编辑AI']);
          b.addEventListener('click', openPanel);
          container.appendChild(b);
          return b;
        })();

    // 清理
    return () => {
      try { if (root && root.unmount) root.unmount(); } catch (e) {}
      mountHost.remove();
      if (btn && btn.remove) btn.remove();
      if (styleEl && styleEl.remove) styleEl.remove();
    };
  },
};
